-- The marketplace: canvas templates (notes, drawings and arrows, plus a look) and themes (a look) that anyone can browse.
-- user_id is NULL for official items. Additive only: the running code ignores it.
CREATE TABLE IF NOT EXISTS market (
  id TEXT PRIMARY KEY,
  kind TEXT NOT NULL, -- 'template' or 'theme'
  user_id TEXT,
  name TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  data TEXT NOT NULL, -- JSON: {"style": {...}, "items": [...]}; a theme has no items
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS market_user ON market (user_id);
-- the official shelf
INSERT OR IGNORE INTO market VALUES ('tpl-project-plan', 'template', NULL, 'Project plan', 'Goal at the top, work flowing through four columns, with timeline and notes below.', '{"style":{},"items":[{"id":"goal","kind":"text","t":1,"x":384,"y":0,"w":384,"s":28,"c":"ink","text":"Goal: what does done look like?"},{"id":"todo","kind":"text","t":2,"x":0,"y":240,"w":240,"s":17,"c":"ink","text":"To do\n\n-"},{"id":"doing","kind":"text","t":3,"x":288,"y":240,"w":240,"s":17,"c":"blue","text":"In progress\n\n-"},{"id":"blocked","kind":"text","t":4,"x":576,"y":240,"w":240,"s":17,"c":"red","text":"Blocked\n\n-"},{"id":"done","kind":"text","t":5,"x":864,"y":240,"w":240,"s":17,"c":"green","text":"Done\n\n-"},{"id":"timeline","kind":"text","t":6,"x":0,"y":720,"w":528,"s":17,"c":"orange","text":"Timeline\n\nStart: \nMilestones: \nDeadline:"},{"id":"notes","kind":"text","t":7,"x":576,"y":720,"w":528,"s":17,"c":"ink","text":"Notes, risks and open questions"},{"id":"e1","kind":"conn","t":100,"a":"goal","b":"todo","c":"ink"},{"id":"e2","kind":"conn","t":101,"a":"goal","b":"doing","c":"ink"},{"id":"e3","kind":"conn","t":102,"a":"goal","b":"blocked","c":"ink"},{"id":"e4","kind":"conn","t":103,"a":"goal","b":"done","c":"ink"}]}', 1791820000000, 1791820000000);
