INSERT OR IGNORE INTO market VALUES ('tpl-weekly-review', 'template', NULL, 'Weekly review', 'Look back at the week, pull out lessons, and set next week''s priorities.', '{"style":{},"items":[{"id":"title","kind":"text","t":1,"x":336,"y":0,"w":432,"s":28,"c":"ink","text":"Week of ____"},{"id":"wins","kind":"text","t":2,"x":0,"y":168,"w":336,"s":17,"c":"green","text":"Wins\n\nWhat went well?\n-"},{"id":"challenges","kind":"text","t":3,"x":384,"y":168,"w":336,"s":17,"c":"red","text":"Challenges\n\nWhat got in the way?\n-"},{"id":"lessons","kind":"text","t":4,"x":768,"y":168,"w":336,"s":17,"c":"orange","text":"Lessons\n\nWhat would I do differently?\n-"},{"id":"energy","kind":"text","t":5,"x":0,"y":528,"w":336,"s":17,"c":"ink","text":"Energy and mood"},{"id":"carry","kind":"text","t":6,"x":384,"y":528,"w":336,"s":17,"c":"ink","text":"Carried over\n\nUnfinished from this week:\n-"},{"id":"next","kind":"text","t":7,"x":768,"y":528,"w":336,"s":17,"c":"blue","text":"Next week: top 3\n\n1. \n2. \n3."},{"id":"e1","kind":"conn","t":100,"a":"wins","b":"lessons","c":"ink"},{"id":"e2","kind":"conn","t":101,"a":"challenges","b":"lessons","c":"ink"},{"id":"e3","kind":"conn","t":102,"a":"lessons","b":"next","c":"ink"},{"id":"e4","kind":"conn","t":103,"a":"carry","b":"next","c":"ink"}]}', 1791820000002, 1791820000002);
